args.sparql:
SELECT DISTINCT ?person ?personLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Vermont_Studio_Center dbp:founder ?founderLiteral .
  ?person rdfs:label ?personLabel .
  FILTER(lang(?personLabel)='en')
  FILTER(lang(?founderLiteral)='en')
  FILTER(CONTAINS(LCASE(STR(?founderLiteral)), LCASE(STR(?personLabel))))
  OPTIONAL { ?person dbo:birthPlace ?birthPlace .
             OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel)='en') } }
}

SELECT ?person ?birthPlace ?birthPlaceLabel WHERE {
  ?person rdfs:label "Jonathan Gregg"@en .
  OPTIONAL { ?person dbo:birthPlace ?birthPlace .
             OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel)='en') } }
}

SELECT ?person ?bp ?bpLabel WHERE {
  ?person rdfs:label "Jonathan Gregg"@en .
  OPTIONAL { ?person dbp:birthPlace ?bp .
             OPTIONAL { ?bp rdfs:label ?bpLabel . FILTER(lang(?bpLabel)='en') } }
}

SELECT ?person ?birthPlace ?birthPlaceLabel WHERE { 
  dbr:Frederick_Osborne rdfs:label ?label . FILTER(lang(?label)='en') .
  OPTIONAL { dbr:Frederick_Osborne dbo:birthPlace ?birthPlace . OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel)='en') } }
  OPTIONAL { dbr:Frederick_Osborne dbp:birthPlace ?bp }
}

SELECT ?name ?person ?personLabel ?birthPlace ?birthPlaceLabel ?birthPlaceLiteral WHERE {
  dbr:Vermont_Studio_Center dbp:founder ?founderLiteral .
  VALUES ?name {"Jonathan Gregg" "Frederick Osborne" "Louise Von Weise"}
  OPTIONAL {
    ?person rdfs:label ?personLabel .
    FILTER(lang(?personLabel)='en')
    FILTER(STR(?personLabel) = ?name)
    OPTIONAL { ?person dbo:birthPlace ?birthPlace .
               OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel)='en') } }
    OPTIONAL { ?person dbp:birthPlace ?birthPlaceLiteral . FILTER(lang(?birthPlaceLiteral)='en') }
  }
}

SELECT ?personLabel ?person ?birthPlace ?birthPlaceLabel ?birthPlaceLiteral WHERE {
  dbr:Vermont_Studio_Center dbp:founder ?founderLiteral .
  VALUES ?personLabel { "Jonathan Gregg"@en "Frederick Osborne"@en "Louise Von Weise"@en }
  OPTIONAL {
    ?person rdfs:label ?personLabel .
    OPTIONAL { ?person dbo:birthPlace ?birthPlace .
               OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel)='en') } }
    OPTIONAL { ?person dbp:birthPlace ?birthPlaceLiteral . FILTER(lang(?birthPlaceLiteral)='en') }
  }
}

output.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?personLabel ?person ?birthPlace ?birthPlaceLabel ?birthPlaceLiteral WHERE {
  dbr:Vermont_Studio_Center dbp:founder ?founderLiteral .
  VALUES ?personLabel {
    "Jonathan Gregg" @en "Frederick Osborne" @en "Louise Von Weise" @en
  }
  OPTIONAL {
    ?person rdfs:label ?personLabel .
    OPTIONAL {
      ?person dbo:birthPlace ?birthPlace .
      OPTIONAL {
        ?birthPlace rdfs:label ?birthPlaceLabel .
        FILTER(lang(?birthPlaceLabel) = 'en')
      }
    }
    OPTIONAL {
      ?person dbp:birthPlace ?birthPlaceLiteral .
      FILTER(lang(?birthPlaceLiteral) = 'en')
    }
  }
}

